def ikili_arama(liste: list, hedef: int) -> int:
    """Sıralı listede ikili arama. O(log n)"""
    sol, sag = 0, len(liste) - 1
    while sol <= sag:
        orta = (sol + sag) // 2
        if liste[orta] == hedef:
            return orta
        elif liste[orta] < hedef:
            sol = orta + 1
        else:
            sag = orta - 1
    return -1

liste = [1, 3, 5, 7, 9, 11, 13]
print(ikili_arama(liste, 7))  # 3

def hizli_sirala(liste: list) -> list:
    """Quick sort — O(n log n) ortalama"""
    if len(liste) <= 1:
        return liste
    pivot = liste[len(liste) // 2]
    kucuk = [x for x in liste if x < pivot]
    esit  = [x for x in liste if x == pivot]
    buyuk = [x for x in liste if x > pivot]
    return hizli_sirala(kucuk) + esit + hizli_sirala(buyuk)

print(hizli_sirala([3, 6, 8, 10, 1, 2, 1]))  # [1, 1, 2, 3, 6, 8, 10]
